              "summary": "- 4Q GPM 50% 조기 돌파 및 1Q 가이던스 상향으로 이익 체력 입증- 심화된 레이저 공급 부족 속 NPO 가세로 스케일업 성장축 다변화- OCS 양산 가속 및 이익 추정치 상향에 따른 밸류에이션 매력 부각",
