          "plainKo": "인공지능이 새 약을 설계하면, 그 설계가 진짜 되는지 실제로 단백질과 유전자를 만들어 시험해 줄 회사가 필요합니다. 이 두 회사가 그 뒷단을 맡으면서 주문과 검사 건수가 늘어난 것이 주가로 이어졌습니다.",
